#!/usr/bin/env bash
# Generate .env.local with random local-only credentials.
# Safe to re-run: existing file is kept unless --force is given.
set -euo pipefail
source "$(dirname "$0")/../lib/common.sh"

if [ -f "$ENV_FILE" ] && [ "${1:-}" != "--force" ]; then
  log "$ENV_FILE already exists; keeping it (use --force to regenerate)"
  exit 0
fi

umask 077
cat > "$ENV_FILE" <<EOF
# Generated by scripts/bootstrap/00-env.sh. Do not commit.
GITEA_ADMIN_USER=admin
GITEA_ADMIN_PASSWORD=$(rand_hex 24)
GITEA_ADMIN_EMAIL=admin@example.local
GITEA_CI_USER=ci-bot
GITEA_CI_PASSWORD=$(rand_hex 24)
GITEA_CI_TOKEN=
GITEA_ARGOCD_USER=argocd
GITEA_ARGOCD_PASSWORD=$(rand_hex 24)
GITEA_ARGOCD_TOKEN=
JENKINS_ADMIN_USER=admin
JENKINS_ADMIN_PASSWORD=$(rand_hex 24)
WEBHOOK_TOKEN=$(rand_hex 24)
REGISTRY_USER=jenkins
REGISTRY_PASSWORD=$(rand_hex 24)
ARGOCD_ADMIN_PASSWORD=$(rand_hex 24)
EOF
chmod 600 "$ENV_FILE"
log "wrote $ENV_FILE (mode 600); values are not printed"
